            { "Kitbash Modular Pistol", "「組み替え」モジュラーピストル" },
            { "Lattice Holographic Sight", "「格子」ホログラフィックサイト" },
            { "Legal: not contraband", "合法：禁制品ではない" },
            { "Let me look at something else.", "ほかのを見てみる。" },
            { "Level {0} repair fee", "レベル{0}修理料金" },
            { "Lever-action rifles", "レバーアクションライフル" },
            { "Lever-action, old-fashioned looks, reliable.", "レバーアクション連発式。古風な外観で、構造の信頼性が高い。" },
